// js
const lookup = first(ctx.reads.leave_catalog).lookup;
const contract = first(ctx.reads.employee_contract);
const employment = ctx.subject.employment;
const started = get(contract, 'service_started_on', get(contract, 'effective_range.from'));
const yearOf = (date) => add_months(started, 12 * Math.max(0, Math.floor(calendar_completed_months(started, date) / 12)));
const dates = ctx.entry.days.map((day) => day.date).toSorted();
const years = dates.map(yearOf).filter((year, index, all) => all.indexOf(year) === index);
// EA s.60E(1), second proviso: absent without permission and without reasonable excuse for more than ten per cent of the working days of the twelve months of continuous service in respect of which the leave accrues, the employee is not entitled to it.
const { weeks, max_absent_share, fallback_days_per_week } = lookup.absence_forfeiture;
const absence = ctx.reads.shift_definition.filter((row) => row.variant.day_type === 'ABS').map((row) => row.id);
const absent = ctx.reads.roster_entry.filter((row) => absence.includes(row.shift_definition_id)).map((row) => row.work_date);
const working = weeks * get(employment, 'terms.normal_days_per_week', fallback_days_per_week);
for (const year of years)
	if (absent.filter((date) => date >= year && date < add_months(year, 12)).length > working * max_absent_share)
		throw 'Absent without leave on more than ' + max_absent_share * 100 + ' per cent of the working days of the service year beginning ' + year + ': no annual leave is due for it.';
if (ctx.event.operation !== 'create') return true;
// EA s.60E(3B): leave of absence without pay exceeding thirty days in the aggregate in any twelve months is disregarded in computing the length of service.
const unpaid = ctx.reads.leave_catalog_entry;
const freed = (id) =>
	unpaid.filter((row) => get(row, 'reverses', '') === id).reduce((total, row) => total + row.days.length, 0);
const slots = unpaid
	.filter((row) => get(row, 'reverses', null) == null)
	.flatMap((row) => row.days.slice(freed(row.id)).map((day) => day.date))
	.filter((date) => date < dates.at(0))
	.toSorted();
const reach = 2 * lookup.service_unpaid_leave_ignored_after_days;
let until = '';
let disregarded = 0;
for (let at = 0; at < slots.length; at += 1) {
	if (at + reach < slots.length && slots.at(at + reach) < add_months(slots.at(at), 12)) until = add_months(slots.at(at), 12);
	if (slots.at(at) < until) disregarded += 1;
}
if (disregarded === 0) return true;
const bands = get(employment, 'engagement', '') === 'PART_TIME' ? lookup.part_time_service_bands : lookup.service_bands;
const [opening] = bands;
const due = (months) =>
	months < opening.service_months
		? Math.round((opening.days * months) / opening.service_months)
		: bands.filter((band) => band.service_months <= months).at(-1).days;
const periods = get(first(ctx.reads.employee_balance), 'account.leave.ANNUAL_LEAVE', {});
for (const year of years) {
	const held = Object.hasOwn(periods, 'MY.S.' + year) ? periods['MY.S.' + year] : {};
	const from = dates.find((date) => yearOf(date) === year);
	const net = Math.max(0, calendar_completed_months(add_days(started, Math.floor(disregarded / 2)), from));
	const left = Math.min(get(held, 'entitled', 0), due(net)) + get(held, 'carried', 0) - get(held, 'used', 0);
	if (dates.filter((date) => yearOf(date) === year).length / 2 > left)
		throw 'Unpaid leave of more than ' + lookup.service_unpaid_leave_ignored_after_days + ' days does not count as service for annual leave: ' + left + ' days are left.';
}
return true;

